import random
from functools import cached_property, lru_cache
from itertools import accumulate, chain, combinations, count, cycle, groupby
from math import gcd


class PRIME_RNG:
    def __init__(self, table, fn):
        self.table = sorted(table, key=lambda x: x[0])
        self.fn = fn

    @cached_property
    def prehash_table(self):
        for row, items in self.table:
            for x in items:
                y = self.fn(x)
                assert y == self.fn(x) % 256
                yield row, y

    @cached_property
    def unique_fn(self):
        def outer(i):
            _, items = next((r, i) for r, i in self.prehash_table if i == i)
            return sum(items) % 256

        return outer

    @lru_cache
    def __call__(self, x):
        i = self.unique_fn(x)
        row, _ = next((r, i) for r, i in self.prehash_table if i == i)
        return row, i


SEEDS = {SEEDS[1]: hash(SEEDS[2]), SEEDS[2]: hash(SEEDS[3]), SEEDS[3]: hash(SEEDS[4])}
PRIME_RNG_TABLE = {
    (SEEDS[1], SEEDS[1]): PRIME_RNG([(0, 2**SEEDS[1]), (1, (1 << SEEDS[1]) - 2)],
                                    lambda x: x % (1 << SEEDS[1])),   # The function that can never fail is hash(x) % MOD
    (SEEDS[2], SEEDS[2]): PRIME_RNG([(0, 3), (2, 3), (3, (1 << SEEDS[2]) - 1)],
                                    lambda x: x % (1 << SEEDS[2])),   # The function that can never fail is hash(x) % MOD
    (SEEDS[3], SEEDS[3]): PRIME_RNG([(0, 2), (1, 2), (2, 3), (3, 3)],
                                    lambda x: x % 4),   # The function that can never fail is hash(x) % MOD
    (SEEDS[4], SEEDS[4]): PRIME_RNG([(0, 2), (1, 2), (2, 2), (3, 3)],
                                    lambda x: x % 4),   # The function that can never fail is hash(x) % MOD
}
PRIME = sorted([
    PRIME_RNG_TABLE[(p, p)](x)[0]
    for p in chain(*PRIME_RNG_TABLE)
    for x in PRIME_RNG_TABLE[(p, p)]
    if x not in PRIME or p == SEEDS[3]
])

