    lines = [(rng.randint(1, 100), rng.randint(1, 100), rng.randint(1, 100)) for _ in range(2)]

    # Same shape as the parent: move points and lines to a new domain (geometry).
    # Solve for the maximum area of a triangle formed by two points and a line.

    point1, point2, point3 = points
    line1, line2 = lines

    # Calculate the area of the triangle formed by point1, point2, and the intersection of line1 and line2.
    def get_triangle_area(point1, point2, intersection):
        return abs((point1[0] - point2[0]) * (intersection[1] - point2[1]) -
                   (point1[1] - point2[1]) * (intersection[0] - point2[0])) / 2

    intersection = None
    if line1[2] != line2[2]:
        intersection = ((line1[1] * line2[2] - line2[1] * line1[2]) / (line1[2] - line2[2]),
                        (line1[2] * line2[1] - line2[2] * line1[1]) / (line1[2] - line2[2]))
    else:
        intersection = None

    max_area = 0
    for i in range(3):
        for j in range(3):
            if i != j:
                triangle_area = get_triangle_area(points[i], points[j], intersection)
                max_area = max(max_area, triangle_area)

    # Independent route: calculate the maximum area by summing the areas of all triangles formed by three points.
    def calculate_areas(points):
        max_area = 0
        for i in range(len(points)):
            for j in range(i + 1, len(points)):
                for k in range(j + 1, len(points)):
                    area = get_triangle_area(points[i], points[j], points[k])
                    max_area = max(max_area, area)
        return max_area

    check_area = calculate_areas(points)
    assert max_area == check_area, f"max_area={max_area} check_area={check_area}"

    problem = (
        "Consider a set of 3 points and 2 lines in a 2D plane. What is the maximum area of a triangle "
        "formed by any two points and one line? Answer only the maximum area as an integer."
    )
    return problem, str(int(max_area))

