    k = rng.randint(2, 14)  # free parameter; widen freely
    n = 3 * k               # n in {6, 9, ..., 42}
    m = rng.randint(1, 7)   # m >= 1 keeps every factor positive

    assert n % 3 == 0 and m >= 1, (
        "invariant violated: n must stay a multiple of 3 and m >= 1"
    )

    max_product = (m + k) ** 3  # = ((n + 3k)/3)^3, exact since n = 3m

    # Independent route: search every positive integer triple summing to n.
    # Since 3 | n, the real optimum m = b = c = n/3 is a lattice point, so
    # the searched maximum must equal the formula.
    check = max(
        (a + k) * (b + k) * (n - a - b + k)
        for a in range(1, n - 1)
        for b in range(1, n - a)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c be positive integers with a + b + c = {n}. "
        f"What is the maximum value of (a + {k})(b + {k})(c + {k})?"
    )

    return problem, str(max_product)

