    n = rng.randint(10, 50)
    k = rng.randint(2, 5)

    # INCLUSION-EXCLUSION: The integers must have equal sum and product to be
    # optimal, so the arithmetic mean of each constraint term must be 1.
    total = n * k * k                  # total number of non-empty k-sets
    exclude_one = k * (n * (n - 1) / 2) # excluding sets with one repeated element
    exclude_two = (n * (n - 1) * (n - 2) / 6) * (k - 2) # excluding sets with two repeated elements
    answer = total - exclude_one + exclude_two

    # Independent route: count every non-empty k-set and subtract the excluded sets.
    check = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for l in range(j + 1, n + 1):
                if k == 3:
                    check += 1
                elif k == 4:
                    if l == n:
                        check += 1
                    else:
                        check += 2
                elif k == 5:
                    # m should be the next element in the range after l
                    for m in range(l + 1, n + 1):
                        if l == n:
                            if m == n:
                                check += 1
                            else:
                                check += 2
                        else:
                            check += 3
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let S be a set with {n} elements. How many subsets of S, excluding those with "
        f"one or two repeated elements, have exactly {k} elements? State only the integer."
    )

    return problem, str(answer)

