def generate(seed):
    rng = random.Random(seed)
    m = rng.randint(5, 15)
    k = rng.randint(2, 6)

    # Find the number of ways to arrange m distinct complex numbers on a grid
    # such that no four of them form a parallelogram.
    # Since 3 | s, the real optimum a = b = c = s/3 is a lattice point, so the searched maximum must equal the formula.
    total = m ** 2  # Total number of ways to arrange m complex numbers on a grid
    parallelograms = sum(
        1
        for i in range(m)
        for j in range(m)
        for l in range(m)
        for n in range(m)
        if (i != l and j != n and abs(l - i) == abs(n - j))
    )
    answer = total - parallelograms

    # Independent route: test every arrangement of m complex numbers on a grid
    # and count the number of arrangements that do not form a parallelogram.
    check = sum(
        1
        for arrangement in itertools.permutations(range(m), m)
        if all(
            abs(arrangement[i] - arrangement[j]) != abs(arrangement[k] - arrangement[l])
            for i in range(m)
            for j in range(m)
            for k in range(m)
            for l in range(m)
            if (i != j and k != l and abs(l - i) == abs(n - j))
        )
    )
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many ways can you arrange {m} distinct complex numbers on a grid "
        f"such that no four of them form a parallelogram?"
    )

    return problem, str(answer)

