    group_permutations = [list(range(n)), list(range(1, n+1)), list(range(2, n+2)), list(range(n-1, -1, -1))]

    # Using invariant properties to define a property that is common among all permutations in the group
    def count_inversions(perm):
        inv_count = 0
        for i in range(n):
            for j in range(i + 1, n):
