    # rely on the mathematical work to seek optimality for a particular s.
    optimal_value = int((s / 3 + k) ** 3)  # = ((s + 3k)/3)^3, exact since s = 3m

    # Second route uses prime factors to compute the same value that we can obtain
    # by finding prime factors of the optimal product.
    def prime_factors(n):
