        factors = {}
        while i * i <= n:
            while (n % i) == 0:
                if i in factors:
                    factors[i] += 1
                else:
                    factors[i] = 1
                n //= i
            i += 1
        if n > 1:
            factors[n] = 1 if n not in factors else factors[n] + 1
