    # to each factor:
    factors_of_n = prime_factors(optimal_value)
    optimized_factors = {p: (e // 3) for p, e in sorted(factors_of_n.items())}
    optimized_value = 1
    for p, e in sorted(optimized_factors.items()):
        optimized_value *= p ** e

    assert optimal_value == optimized_value, f"optimal_value={optimal_value} optimized_value={optimized_value}"

    problem = (
        f"Let \( n \) be an integer given by \( n = ({s} + 3 \cdot {k})^3 \). "
        f"What is the largest possible value of \( x \) such that \( x^3 = n \)? "
