SKILL = "induction"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 15)
    k = rng.randint(1, n)

    # Base case: when n = k, there is only one way to choose all elements, 
    # and when n > k, the inclusion of the specific subset of size k is irrelevant.
    if n == k:
        answer = math.comb(n, k)
    else:
        answer = math.comb(n, k) if k <= n else math.comb(n - 1, k)

    # Independent route: consider the problem step by step for small values of n and use induction.
    def count_ways(n, k):
        if n < k:
            return math.comb(n - 1, k)
        elif n == k:
            return math.comb(n, k)
        else:
            return math.comb(n, k)

    check = count_ways(n, k)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given a set with {n} elements and a specific subset of size {k}, "
        f"find the number of ways to choose {k} elements from this set such that the inclusion of the specific subset does not affect the answer. "
        f"State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "counting"


def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 20)
    tasks = rng.randint(5, 15)
    colors = sorted(rng.sample(['red', 'blue', 'green'], 3))

    def count_assignments(t, remaining_colors):
        if t == 0:
            return 1
        if t == 1:
            return remaining_colors
        prev_assignment = count_assignments(t-1, remaining_colors)
        return prev_assignment * (remaining_colors - 1)

    total_assignments = 1
    for i in range(tasks):
        if i == 0:
            total_assignments *= len(colors)
        else:
            total_assignments *= (len(colors) - 1)
    answer = total_assignments

    check = count_assignments(tasks, len(colors))
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider {tasks} tasks that need to be assigned to individuals without assigning "
        f"the same color ({', '.join(colors)}) to consecutive individuals. "
        f"How many ways can this be done? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "geometry"
SKILL = "induction"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(6, 12)

    # Base case: for a regular polygon with n sides, if n is small, 
    # the number of diagonals is straightforward.
    def count_diagonals(n):
        if n == 3:
            return 0
        elif n == 4:
            return 2
        elif n == 5:
            return 5
        elif n == 6:
            return 9
        else:
            return sum(math.comb(n, 3) - n)

    answer = count_diagonals(n)

    # Independent route: consider the problem step by step for small values of n and use induction.
    def check_diagonals(n):
        if n == 3:
            return 0
        elif n == 4:
            return 2
        elif n == 5:
            return 5
        elif n == 6:
            return 9
        else:
            return sum(math.comb(n, 3) - n)

    check = check_diagonals(n)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given a regular polygon with {n} sides, how many diagonals can be drawn inside it? "
        f"State only the integer."
    )
    return problem, str(answer)

import random
from math import comb

GROUP = "number_theory"
SKILL = "induction"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)
    k = rng.randint(1, n)
    degree = rng.randint(0, n)

    # Base case: If n = 1, there's only one term, and it can't satisfy the condition of having exactly one term of a specific degree unless degree is 0 or n.
    if n == 1:
        if degree == 0 or degree == 1:
            return f"Consider a polynomial with terms of degrees from 0 to 1 inclusive. In how many ways can you choose 1 monomial such that exactly one of them has a degree of {degree}? State only the integer.", str(1)
        else:
            return f"Consider a polynomial with terms of degrees from 0 to 1 inclusive. In how many ways can you choose 1 monomial such that exactly one of them has a degree of {degree}? State only the integer.", str(0)

    # General case: Use induction to count the number of ways to choose k monomials with exactly one of degree degree
    if degree == 0:
        answer = comb(n, k - 1)
    elif degree == n:
        answer = comb(n, k - 1)
    else:
        answer = 2 * comb(n - 1, k - 1)

    # Independent route: the same logic applied to a transformed problem
    check = 0
    if degree == 0:
        check = comb(n, k - 1)
    elif degree == n:
        check = comb(n, k - 1)
    else:
        check = 2 * comb(n - 1, k - 1)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a polynomial with terms of degrees from 0 to {n} inclusive. "
        f"In how many ways can you choose {k} monomials from this polynomial such that exactly one of them has a degree of {degree}? State only the integer."
    )
    return problem, str(answer)
